  'prompt.p1.style.analytical': 'analytical thinker, asks questions',
  'prompt.p1.style.direct': 'short and direct',
  'prompt.p1.style.emotional': 'expresses feelings at length',
  'prompt.p1.style.balanced': 'balanced communication',
  'prompt.p1.style.unknown': 'not yet determined',
  'prompt.p1.values': '[VALUES]: {{list}}.',
  'prompt.p1.relationships': '[RELATIONSHIPS]: {{summary}}.',
  'prompt.p1.rel.mother': 'mother', 'prompt.p1.rel.father': 'father', 'prompt.p1.rel.partner': 'partner',
  'prompt.p1.rel.sibling': 'sibling', 'prompt.p1.rel.boss': 'boss', 'prompt.p1.rel.friend': 'friend',
